def ideals(n):
 if n==0:return [0,1]
 prev=ideals(n-1); shift=1<<(n-1)
 return [a|(b<<shift) for a in prev for b in prev if b&a==b]

def bier(K,n):
 facets=[]
 for f in range(1<<n):
  if not K>>f&1:continue
  for i in range(n):
